// Пример с customHooks для вызова серверного действия при изменении Select
{
    "type": "Select",
    "name": "window-selector", 
    // ... другие props и model ...
    "customHooks": {
        "change": [
            {
                // Указываем КЛИЕНТСКОЕ действие для отправки данных 
                "action": "sendData", // Это действие вызывает ActionManager.sendData
                // Внутри data передаем имя СЕРВЕРНОГО действия и параметры для сбора данных
                "data": { 
                    "sendTo": "program-section/windowChange", // Имя СЕРВЕРНОГО действия
                    "form": "program-section", // Форма, откуда брать данные
                    "field": "selectedWindow"  // Поле, значение которого включить в payload
                } 
            }
        ]
    }
}

// Пример кнопки submit в диалоге
{
    "type": "submit",
    "props": {
        "label": "Сохранить",
        "form": "editRecordForm", // Идентификатор формы для formData
        "action": "saveRecord"     // Имя СЕРВЕРНОГО действия для обработки
    }
}
